import { cookies, headers } from 'next/headers';

function getPreferredLanguage(acceptLanguage: string | null): string {
  if (!acceptLanguage) return 'Unknown';
  // Accept-Language format: "en-US,en;q=0.9,es;q=0.8" - first entry is preferred
  const firstLocale = acceptLanguage.split(',')[0]?.trim();
  return firstLocale || 'Unknown';
}

export default async function ThemePreferences() {
  const [cookieStore, headerStore] = await Promise.all([
    cookies(),
    headers(),
  ]);

  const themeCookie = cookieStore.get('theme');
  const theme = themeCookie?.value ?? 'light';

  const acceptLanguage = headerStore.get('accept-language');
  const preferredLanguage = getPreferredLanguage(acceptLanguage);

  return (
    <div>
      <p>
        <strong>Theme:</strong> {theme}
      </p>
      <p>
        <strong>Preferred language:</strong> {preferredLanguage}
      </p>
    </div>
  );
}

